-- National atmospheric distillation capacity, crude slate and notes.
-- Slugs are derived from the name (accents folded) so they stay stable and URL-safe.

delete from countries;
insert into countries (name, slug, region_code, capacity_kbd, slate_code, slate_detail, note)
select
  name,
  trim(both '-' from regexp_replace(lower(translate(name, 'ôçéáí&', 'oceai-')), '[^a-z0-9]+', '-', 'g')),
  region_code, capacity_kbd, slate_code, slate_detail, note
from jsonb_to_recordset($json$
[
{"name":"China","region_code":"APAC","capacity_kbd":18800,"slate_code":"sour","slate_detail":"Medium & heavy sour import blend — Saudi Arab Light/Heavy, Russian ESPO & Urals, Iranian Heavy, Iraqi Basrah, Brazilian pre-salt","note":"World's largest refiner since 2023. Record 11.6 mb/d of crude imports in 2025, of which at least 2.6 mb/d sanctioned. New coastal complexes (Zhoushan, Yulong, Hengli) are deep-conversion and petrochemical-integrated; Shandong teapots are simpler but numerous."},
{"name":"United States","region_code":"NA","capacity_kbd":18200,"slate_code":"heavy","slate_detail":"Barbell: domestic light sweet shale (WTI ~40° API) plus imported heavy sour (WCS 20.5°, Maya 21.5°)","note":"Capacity fell from 18.45 to 18.2 mb/d over 2025 as LyondellBasell Houston and Phillips 66 Los Angeles closed. 130 operable refineries. Gulf Coast averages >13 Nelson — the deepest conversion fleet in the world."},
{"name":"Russia","region_code":"RUS","capacity_kbd":6700,"slate_code":"sour","slate_detail":"Domestic Urals (31° API, ~1.6% S), Siberian Light, ESPO","note":"Nameplate only. Essentially every major refinery in European Russia was struck by drones between 2025 and mid-2026; reported losses have reached ~25% of capacity, triggering fuel export bans. Omsk and Angarsk remain unhit."},
{"name":"India","region_code":"APAC","capacity_kbd":5100,"slate_code":"heavy","slate_detail":"Heavy sour by design — Basrah Heavy, Urals, Venezuelan Merey, West African and US grades opportunistically","note":"Jamnagar (Reliance) runs at a Nelson index near 21, the highest in the world. Nayara's Vadinar plant, 49% Rosneft-owned, was sanctioned by the EU in 2025. India is the marginal buyer of discounted heavy sour."},
{"name":"South Korea","region_code":"APAC","capacity_kbd":3500,"slate_code":"sour","slate_detail":"Middle East medium and heavy sour — Saudi, Kuwaiti, UAE — plus condensate splitters","note":"Four very large, very complex complexes (Ulsan, Yeosu, Onsan, Daesan). Export-oriented; among the highest average complexity of any national fleet."},
{"name":"Saudi Arabia","region_code":"ME","capacity_kbd":3289,"slate_code":"sour","slate_detail":"Own Arab Light (33°/1.8% S), Arab Medium and Arab Heavy (27°/2.9% S)","note":"Aramco has added SATORP, Jazan and equity stakes abroad (Motiva Port Arthur, S-Oil, Fujian). Strategy is to place its own sour barrels into refineries it controls."},
{"name":"Japan","region_code":"APAC","capacity_kbd":3050,"slate_code":"sour","slate_detail":"Middle East medium sour, largely Saudi and UAE term barrels","note":"Structurally shrinking with domestic demand; capacity has fallen by roughly a third since 2000. Moderate complexity, strong desulphurisation but limited coking."},
{"name":"Iran","region_code":"ME","capacity_kbd":2460,"slate_code":"sour","slate_detail":"Domestic Iranian Heavy (30°/~2% S) and Light, plus Persian Gulf Star condensate","note":"Persian Gulf Star is one of the world's largest condensate refineries. Sanctions constrain catalyst and equipment supply more than crude availability."},
{"name":"Brazil","region_code":"LAT","capacity_kbd":2290,"slate_code":"mixed","slate_detail":"Domestic pre-salt: Tupi/Lula and Búzios, ~29° API but unusually low sulphur (~0.3%)","note":"Petrobras crude is medium-density yet sweet — an awkward fit for a fleet built for it, and increasingly exported to China while Brazil imports products."},
{"name":"Germany","region_code":"EUR","capacity_kbd":1980,"slate_code":"mixed","slate_detail":"Post-2022 mix of WTI, Norwegian, Kazakh CPC and West African, replacing Urals","note":"Schwedt (PCK), under German trusteeship of Rosneft's stake, was engineered for Urals via Druzhba and has struggled since. BP shut a third of Gelsenkirchen; Shell closed Wesseling in 2025."},
{"name":"Canada","region_code":"NA","capacity_kbd":1954,"slate_code":"heavy","slate_detail":"Western Canadian Select (20.5°/3.5% S) and synthetic crude in the west; imported light sweet in the east","note":"Average Nelson just above 8 — less heavy-capable than the US Midwest despite producing the heavy barrel. Irving Saint John, the largest plant, runs imported grades."},
{"name":"Italy","region_code":"EUR","capacity_kbd":1803,"slate_code":"heavy","slate_detail":"Mediterranean sour grades, Iraqi, Kazakh and Libyan barrels","note":"ISAB Priolo in Sicily — formerly Lukoil-owned, forcibly sold in 2023 — is one of Europe's few genuinely deep-conversion plants."},
{"name":"Spain","region_code":"EUR","capacity_kbd":1590,"slate_code":"heavy","slate_detail":"Heavy sour including Mexican Maya, plus US WTI and West African grades","note":"Repsol and Moeve (ex-Cepsa) run one of Europe's most complex fleets: Cartagena and Bilbao have real coking capacity, unusual for the continent."},
{"name":"Mexico","region_code":"LAT","capacity_kbd":1558,"slate_code":"heavy","slate_detail":"Domestic Maya (21.5°/3.6% S), Isthmus and Olmeca","note":"Chronic underutilisation. The new 340 kb/d Olmeca refinery at Dos Bocas was intended to consume Maya domestically; its slow ramp has kept those barrels flowing to the US Gulf."},
{"name":"Kuwait","region_code":"ME","capacity_kbd":1415,"slate_code":"heavy","slate_detail":"Kuwait Export Blend (31°/2.5% S) and heavier domestic streams","note":"Al-Zour (615 kb/d) was purpose-built to convert high-sulphur residue into IMO-compliant low-sulphur fuel oil — one of the most consequential new plants of the decade."},
{"name":"Venezuela","region_code":"LAT","capacity_kbd":1303,"slate_code":"heavy","slate_detail":"Extra-heavy Merey 16 and Boscan (~10° API, 5.5% S) blended with imported diluent","note":"Nameplate is fiction: the Paraguaná complex and Puerto La Cruz have run at a small fraction of capacity for years. The crude itself needs upgraders as much as refineries."},
{"name":"Singapore","region_code":"APAC","capacity_kbd":1302,"slate_code":"sour","slate_detail":"Fully imported — Middle East sour, regional sweet, condensate","note":"Pure refining and petrochemical hub with no domestic crude. Shell's Bukom sale to Chandra Asri/Glencore in 2024 marked the end of an era for Western majors in the region."},
{"name":"United Arab Emirates","region_code":"ME","capacity_kbd":1271,"slate_code":"mixed","slate_detail":"Murban (40°/0.75% S) — light but slightly sour — and Upper Zakum medium sour","note":"Ruwais (817 kb/d) is among the largest single sites in the world. Murban's promotion to a futures benchmark in 2021 was a deliberate move to price the UAE's own barrel."},
{"name":"Indonesia","region_code":"APAC","capacity_kbd":1259,"slate_code":"mixed","slate_detail":"Domestic Minas/Duri plus Middle East and West African imports","note":"Duri is a rarity: heavy (21° API) but almost sulphur-free. Pertamina's fleet is old and under a long-running upgrade programme."},
{"name":"Thailand","region_code":"APAC","capacity_kbd":1242,"slate_code":"sour","slate_detail":"Middle East sour with regional sweet blending","note":"Medium complexity; refiners are integrated with domestic petrochemicals."},
{"name":"Netherlands","region_code":"EUR","capacity_kbd":1241,"slate_code":"mixed","slate_detail":"North Sea, West African and Middle East grades via Rotterdam","note":"Shell Pernis (~400 kb/d) is the largest refinery in Europe. Rotterdam is the continent's product blending and storage hub as much as a refining centre."},
{"name":"Iraq","region_code":"ME","capacity_kbd":1219,"slate_code":"sour","slate_detail":"Domestic Basrah Medium (29°/2.9% S) and Basrah Heavy (24°/4% S)","note":"Low average complexity and heavy fuel oil surplus. Basrah Heavy is one of the sourest widely traded grades and prices accordingly."},
{"name":"Taiwan","region_code":"APAC","capacity_kbd":1200,"slate_code":"sour","slate_detail":"Middle East sour term barrels","note":"Formosa's Mailiao complex (~540 kb/d) is fully petrochemical-integrated; CPC runs the rest."},
{"name":"United Kingdom","region_code":"EUR","capacity_kbd":1000,"slate_code":"mixed","slate_detail":"North Sea light sweet plus imported grades","note":"Down sharply: Grangemouth (150 kb/d) stopped processing crude in 2025 and Prax Lindsey entered administration. Five refineries remain, led by Fawley and Humber — the latter one of the few dedicated to petroleum coke."},
{"name":"Malaysia","region_code":"APAC","capacity_kbd":1155,"slate_code":"mixed","slate_detail":"Regional sweet (Tapis, Miri) plus Middle East sour at Pengerang","note":"Pengerang RAPID (300 kb/d) is modern and complex; Aramco exited its stake in 2025 after years of dispute."},
{"name":"France","region_code":"EUR","capacity_kbd":1145,"slate_code":"mixed","slate_detail":"West African, North Sea and Kazakh grades","note":"TotalEnergies has converted Grandpuits and La Mède away from crude; Gonfreville and Donges carry the remaining fleet."},
{"name":"Nigeria","region_code":"AFR","capacity_kbd":1030,"slate_code":"sweet","slate_detail":"Light sweet — Bonny Light (35°/0.15% S), Qua Iboe, plus imported WTI Midland and Libyan Sharara","note":"Dangote (650 kb/d) accounts for nearly all functioning capacity; the NNPC plants at Port Harcourt, Warri and Kaduna have been largely non-operational for years. Feedstock security, not conversion depth, is the constraint."},
{"name":"Egypt","region_code":"AFR","capacity_kbd":825,"slate_code":"mixed","slate_detail":"Domestic Western Desert and Gulf of Suez crude plus imports","note":"Largest African fleet by plant count; MIDOR at Alexandria is the most modern."},
{"name":"Turkey","region_code":"ME","capacity_kbd":822,"slate_code":"sour","slate_detail":"Was a large Urals buyer; now a mix of Russian, Iraqi and Kazakh grades","note":"Tüpraş's İzmit and İzmir plants plus SOCAR's STAR at Aliağa. Turkey became a major re-exporter of products refined from discounted Russian crude after 2022."},
{"name":"Algeria","region_code":"AFR","capacity_kbd":657,"slate_code":"sweet","slate_detail":"Domestic Saharan Blend (45°/0.09% S) — among the lightest, sweetest crudes traded","note":"Sonatrach's fleet is simple by design; it does not need conversion depth for this feed."},
{"name":"Belgium","region_code":"EUR","capacity_kbd":645,"slate_code":"mixed","slate_detail":"North Sea and West African grades via Antwerp","note":"TotalEnergies Antwerp is one of the more complex plants in northern Europe, tightly integrated with the port's petrochemical cluster."},
{"name":"Argentina","region_code":"LAT","capacity_kbd":600,"slate_code":"sweet","slate_detail":"Increasingly Vaca Muerta light sweet (Medanito, ~35°/0.5% S) displacing Escalante heavy","note":"Domestic shale growth is reversing decades of crude imports; refiners are re-tuning toward lighter feed."},
{"name":"Belarus","region_code":"RUS","capacity_kbd":475,"slate_code":"sour","slate_detail":"Russian Urals via Druzhba","note":"Mozyr and Naftan were built as export refineries for the Soviet system and remain wholly dependent on Russian crude."},
{"name":"Poland","region_code":"EUR","capacity_kbd":583,"slate_code":"sour","slate_detail":"Saudi Arab Light and Norwegian grades, replacing Urals from 2023","note":"Orlen's Płock (~327 kb/d) and Gdańsk. One of the more decisive European pivots away from Russian feedstock, achieved largely through Aramco term contracts."},
{"name":"Greece","region_code":"EUR","capacity_kbd":528,"slate_code":"sour","slate_detail":"Mediterranean and Middle East sour, historically Iranian and Russian","note":"Motor Oil Corinth and HelleniQ Elefsina are relatively complex for their size and export heavily."},
{"name":"Colombia","region_code":"LAT","capacity_kbd":501,"slate_code":"heavy","slate_detail":"Domestic Castilla Blend (18.8°/2% S) and Vasconia","note":"Cartagena's post-2015 upgrade gave Ecopetrol genuine heavy-crude capability."},
{"name":"Sweden","region_code":"EUR","capacity_kbd":454,"slate_code":"mixed","slate_detail":"North Sea and Russian-free imports since 2022","note":"Preem's Lysekil is the largest and, unusually for Europe, has real conversion depth."},
{"name":"Pakistan","region_code":"APAC","capacity_kbd":450,"slate_code":"mixed","slate_detail":"Middle East sour, mostly Saudi and UAE term supply","note":"Small, simple plants with persistent furnace-oil surplus."},
{"name":"Kazakhstan","region_code":"RUS","capacity_kbd":400,"slate_code":"mixed","slate_detail":"Domestic Tengiz and Karachaganak light sour; CPC Blend (45°/0.55% S) is exported","note":"Atyrau, Pavlodar and Shymkent were modernised in the late 2010s. Pavlodar is configured for West Siberian crude."},
{"name":"Bahrain","region_code":"ME","capacity_kbd":380,"slate_code":"sour","slate_detail":"Domestic Bahrain field plus Saudi Arab Light via pipeline","note":"The Sitra modernisation lifted capacity and complexity substantially, completing a wave of ~1.4 mb/d of new GCC capacity."},
{"name":"Vietnam","region_code":"APAC","capacity_kbd":367,"slate_code":"mixed","slate_detail":"Domestic Bach Ho sweet at Dung Quat; Kuwaiti sour at Nghi Son","note":"Nghi Son was built around a Kuwaiti crude supply agreement — a supply-security design, not a market one."},
{"name":"Libya","region_code":"AFR","capacity_kbd":380,"slate_code":"sweet","slate_detail":"Domestic Es Sider (37°/0.45% S) and Sharara (43°/0.07% S)","note":"Zawia and Ras Lanuf are damaged and partly idle; Libya exports crude and imports products. Sharara has become a swing feedstock for Dangote."},
{"name":"Qatar","region_code":"ME","capacity_kbd":340,"slate_code":"cond","slate_detail":"Largely condensate from the North Field, plus some crude","note":"Ras Laffan's condensate splitters dominate; the coming Laffan expansion is naphtha- and jet-oriented."},
{"name":"Israel","region_code":"ME","capacity_kbd":301,"slate_code":"mixed","slate_detail":"Azeri BTC and Kazakh grades via the Mediterranean","note":"Haifa and Ashdod; Haifa faces long-running pressure to close on environmental grounds."},
{"name":"Oman","region_code":"ME","capacity_kbd":300,"slate_code":"sour","slate_detail":"Oman Blend (33°/1.2% S) plus Kuwaiti crude at Duqm","note":"OQ8's Duqm refinery (230 kb/d), a joint venture with Kuwait, is the newest deep-conversion plant in the region."},
{"name":"Peru","region_code":"LAT","capacity_kbd":283,"slate_code":"heavy","slate_detail":"Imported heavy and domestic jungle crude","note":"Talara's rebuild gave Petroperú a modern coker — and a debt problem large enough to threaten the company."},
{"name":"Romania","region_code":"EUR","capacity_kbd":252,"slate_code":"sour","slate_detail":"Domestic Urals-like grades and Black Sea imports","note":"Petrobrazi and Petromidia; Lukoil's ownership of Petrotel has made it a sanctions pressure point."},
{"name":"Ukraine","region_code":"RUS","capacity_kbd":250,"slate_code":"sour","slate_detail":"Historically Urals and Azeri crude","note":"Kremenchuk, the only significant refinery, has been repeatedly struck since 2022. Product supply is now overwhelmingly imported."},
{"name":"Chile","region_code":"LAT","capacity_kbd":242,"slate_code":"mixed","slate_detail":"Fully imported — Ecuadorian, Brazilian and West African grades","note":"ENAP's Aconcagua and Bío Bío; no domestic crude of consequence."},
{"name":"Australia","region_code":"APAC","capacity_kbd":235,"slate_code":"sweet","slate_detail":"Regional and Middle East light sweet","note":"Only Geelong (Viva) and Lytton (Ampol) survive after four closures since 2020. Australia now imports the large majority of its fuel."},
{"name":"Norway","region_code":"EUR","capacity_kbd":226,"slate_code":"mixed","slate_detail":"Domestic North Sea grades including Johan Sverdrup (28°/0.8% S)","note":"Mongstad is the sole significant refinery; Slagen closed in 2021. Sverdrup is medium and slightly sour — heavier than most people assume Norwegian crude to be."},
{"name":"Portugal","region_code":"EUR","capacity_kbd":225,"slate_code":"mixed","slate_detail":"West African and North Sea grades","note":"Galp's Sines is the only remaining refinery after Matosinhos closed in 2021."},
{"name":"Turkmenistan","region_code":"RUS","capacity_kbd":240,"slate_code":"sweet","slate_detail":"Domestic light sweet Caspian crude","note":"Turkmenbashi is landlocked and export-constrained."},
{"name":"South Africa","region_code":"AFR","capacity_kbd":215,"slate_code":"mixed","slate_detail":"Historically imported Middle East and West African crude","note":"Nameplate flatters reality: Sapref is shut, Engen's Durban plant converted to a terminal, and Natref is the main survivor. South Africa is now heavily import-dependent."},
{"name":"Uzbekistan","region_code":"RUS","capacity_kbd":222,"slate_code":"cond","slate_detail":"Domestic condensate and light crude","note":"Bukhara and Fergana; gas-condensate led."},
{"name":"Finland","region_code":"EUR","capacity_kbd":206,"slate_code":"mixed","slate_detail":"North Sea and non-Russian grades since 2022","note":"Neste's Porvoo is complex and increasingly oriented toward renewable feedstock alongside crude."},
{"name":"Morocco","region_code":"AFR","capacity_kbd":200,"slate_code":"mixed","slate_detail":"Formerly imported Middle East grades","note":"Samir, the sole refinery, has been idle since 2015. Morocco imports all its products."},
{"name":"Austria","region_code":"EUR","capacity_kbd":193,"slate_code":"mixed","slate_detail":"Caspian, North African and Middle East grades via Trieste","note":"OMV's Schwechat is inland and pipeline-fed from the Adriatic."},
{"name":"Denmark","region_code":"EUR","capacity_kbd":181,"slate_code":"mixed","slate_detail":"North Sea grades","note":"Fredericia (Shell/Postlane) is the last Danish refinery after Kalundborg's closure was announced."},
{"name":"Philippines","region_code":"APAC","capacity_kbd":180,"slate_code":"mixed","slate_detail":"Middle East sour and regional sweet","note":"Petron's Limay plant is the only refinery since Shell converted Tabangao to an import terminal in 2020."},
{"name":"Czechia","region_code":"EUR","capacity_kbd":175,"slate_code":"sour","slate_detail":"Urals via Druzhba historically; now shifting to TAL pipeline supply from Trieste","note":"Orlen Unipetrol's Litvínov and Kralupy. The TAL-Plus expansion was explicitly built to end Russian dependence."},
{"name":"Angola","region_code":"AFR","capacity_kbd":120,"slate_code":"sweet","slate_detail":"Domestic Girassol and Cabinda light sweet","note":"Luanda is small and simple; the long-delayed Lobito and Cabinda projects would change the picture if completed."},
{"name":"Hungary","region_code":"EUR","capacity_kbd":165,"slate_code":"sour","slate_detail":"Still Urals via Druzhba under EU exemption","note":"MOL's Százhalombatta was engineered specifically for Urals; converting it fully to seaborne alternatives is a multi-year capital programme."},
{"name":"Azerbaijan","region_code":"RUS","capacity_kbd":200,"slate_code":"mixed","slate_detail":"Domestic Azeri Light (35°/0.15% S)","note":"Heydar Aliyev refinery at Baku; modernised to Euro-5 specification."},
{"name":"Ecuador","region_code":"LAT","capacity_kbd":175,"slate_code":"heavy","slate_detail":"Domestic Oriente and Napo heavy sour","note":"Esmeraldas is the largest; chronic maintenance problems keep utilisation low."},
{"name":"Switzerland","region_code":"EUR","capacity_kbd":68,"slate_code":"mixed","slate_detail":"Pipeline-fed Mediterranean grades","note":"Cressier is the only remaining refinery."},
{"name":"Bangladesh","region_code":"APAC","capacity_kbd":43,"slate_code":"mixed","slate_detail":"Middle East sour term supply","note":"Eastern Refinery in Chattogram; an expansion has been under discussion for a decade."},
{"name":"Bulgaria","region_code":"EUR","capacity_kbd":190,"slate_code":"sour","slate_detail":"Urals historically; Middle East and Kazakh grades since 2024","note":"Lukoil Neftohim Burgas held the EU's last major Urals exemption. It was placed under state-appointed management in 2025 — the sharpest example of a refinery's crude design becoming a sovereignty question."},
{"name":"Lithuania","region_code":"EUR","capacity_kbd":190,"slate_code":"mixed","slate_detail":"Seaborne grades via Būtingė since Druzhba supply was cut in 2006","note":"Orlen Lietuva at Mažeikiai is the Baltic states' only refinery and has been a strategic asset in every regional energy dispute since."},
{"name":"Brunei","region_code":"APAC","capacity_kbd":175,"slate_code":"sweet","slate_detail":"Regional light sweet","note":"Hengyi's Pulau Muara Besar plant is Chinese-owned and export-oriented — a Belt and Road refining outpost."},
{"name":"Curaçao","region_code":"LAT","capacity_kbd":335,"slate_code":"heavy","slate_detail":"Venezuelan Merey, historically","note":"The Isla refinery was leased by PDVSA for decades and has been effectively idle since 2019. Nameplate only."},
{"name":"Trinidad & Tobago","region_code":"LAT","capacity_kbd":160,"slate_code":"mixed","slate_detail":"Domestic and imported grades","note":"Pointe-à-Pierre has been shut since 2018; repeated sale processes have failed."},
{"name":"Cuba","region_code":"LAT","capacity_kbd":130,"slate_code":"heavy","slate_detail":"Venezuelan and domestic heavy crude","note":"Cienfuegos and Havana run far below nameplate; fuel scarcity is chronic."},
{"name":"Slovakia","region_code":"EUR","capacity_kbd":124,"slate_code":"sour","slate_detail":"Urals via Druzhba","note":"MOL's Slovnaft at Bratislava, like Hungary's Danube refinery, was built for Russian crude and still runs it under exemption."},
{"name":"Sudan","region_code":"AFR","capacity_kbd":100,"slate_code":"mixed","slate_detail":"Domestic Nile and Dar Blend","note":"Khartoum refinery has been damaged in the civil war. Dar Blend is unusually acidic, limiting where it can be processed."},
{"name":"Serbia","region_code":"EUR","capacity_kbd":96,"slate_code":"sour","slate_detail":"Seaborne grades via the JANAF pipeline","note":"NIS Pančevo is majority Gazprom-owned and was hit by US sanctions in 2025, threatening its crude supply through Croatia."},
{"name":"Croatia","region_code":"EUR","capacity_kbd":90,"slate_code":"mixed","slate_detail":"Seaborne Mediterranean and Caspian grades","note":"INA's Rijeka refinery; Sisak has been converted. JANAF's pipeline gives Croatia leverage over landlocked neighbours."},
{"name":"Côte d'Ivoire","region_code":"AFR","capacity_kbd":80,"slate_code":"sweet","slate_detail":"West African light sweet","note":"SIR at Abidjan supplies much of francophone West Africa."},
{"name":"Bolivia","region_code":"LAT","capacity_kbd":60,"slate_code":"sweet","slate_detail":"Domestic light condensate-rich crude","note":"Small plants at Cochabamba and Santa Cruz; chronic diesel import dependence."},
{"name":"Uruguay","region_code":"LAT","capacity_kbd":50,"slate_code":"mixed","slate_detail":"Imported West African and Middle East grades","note":"ANCAP's La Teja is the country's sole refinery."},
{"name":"Sri Lanka","region_code":"APAC","capacity_kbd":50,"slate_code":"mixed","slate_detail":"Middle East and Russian grades","note":"Sapugaskanda is small and simple; the proposed Hambantota project would dwarf it."},
{"name":"Ghana","region_code":"AFR","capacity_kbd":45,"slate_code":"sweet","slate_detail":"Domestic Jubilee light sweet","note":"Tema Oil Refinery operates intermittently."},
{"name":"Tunisia","region_code":"AFR","capacity_kbd":34,"slate_code":"mixed","slate_detail":"Imported and domestic crude","note":"Bizerte is small and supplies domestic demand only."},
{"name":"New Zealand","region_code":"APAC","capacity_kbd":0,"slate_code":"sweet","slate_detail":"—","note":"Marsden Point ceased refining in 2022 and now operates as an import terminal. Nameplate capacity is zero."}
]
$json$) as x(name text, region_code text, capacity_kbd int, slate_code text, slate_detail text, note text);
